const workflowCatalog = `-- name: WorkflowCatalog :many
SELECT l.id, l.name, l.description, l.latest_version, l.origin, l.updated_at,COALESCE(v.yaml,'')::text AS yaml,(v.lib_id IS NOT NULL)::boolean AS has_version
FROM lib_workflows l LEFT JOIN lib_workflow_versions v ON v.lib_id=l.id AND v.version=l.latest_version ORDER BY l.origin DESC,l.name
`

type WorkflowCatalogRow struct {
	LibWorkflow LibWorkflow
	Yaml        string
	HasVersion  bool
}

func (q *Queries) WorkflowCatalog(ctx context.Context) ([]WorkflowCatalogRow, error) {
	rows, err := q.db.QueryContext(ctx, workflowCatalog)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WorkflowCatalogRow
	for rows.Next() {
		var i WorkflowCatalogRow
		if err := rows.Scan(
			&i.LibWorkflow.ID,
			&i.LibWorkflow.Name,
			&i.LibWorkflow.Description,
			&i.LibWorkflow.LatestVersion,
			&i.LibWorkflow.Origin,
			&i.LibWorkflow.UpdatedAt,
			&i.Yaml,
			&i.HasVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

